insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('5015a013-97ab-45fe-841e-6c53ce4e14c0','sd-tumbuhan',1,'lesson','SD','kosakata','Kenali tumbuhan dan buah','{"description":"Kenali mangga, pepaya, dan jeruk lewat gambar dan isyarat.","emoji":"🥭","word":"Mangga","words":["Mangga","Pepaya","Jeruk"],"time":8,"intro":"Kamu akan mengenali tiga buah yang muncul pada video dan Kamus Visual SD.","explanation":"Mangga tumbuh pada pohon mangga. Pepaya tumbuh pada tanaman pepaya. Jeruk memiliki kulit tebal dan bagian dalam berupa ulas.","tip":"Perhatikan gambar buah, baca namanya, lalu amati bagian video yang sesuai.","visual":"🥭 🌱 🍊","level":"Dasar","wordEntry":{"word":"Mangga","emoji":"🥭","category":"Tumbuhan","meaning":"Buah yang tumbuh pada pohon mangga.","example":"Pohon mangga menghasilkan buah mangga.","videoId":"iDDkYTki6pU","start":80,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}},"relatedWords":[{"word":"Mangga","emoji":"🥭","category":"Tumbuhan","meaning":"Buah yang tumbuh pada pohon mangga.","example":"Pohon mangga menghasilkan buah mangga.","videoId":"iDDkYTki6pU","start":80,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}},{"word":"Pepaya","emoji":"🌱","category":"Tumbuhan","meaning":"Buah yang tumbuh pada tanaman pepaya.","example":"Kita menghitung buah pepaya pada gambar.","videoId":"iDDkYTki6pU","start":165,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}},{"word":"Jeruk","emoji":"🍊","category":"Tumbuhan","meaning":"Buah berkulit tebal dengan bagian dalam berupa beberapa ulas.","example":"Ada dua buah jeruk pada gambar.","videoId":"iDDkYTki6pU","start":225,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}}],"example":"Pohon mangga menghasilkan buah mangga.","video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}}'::jsonb,'published') on conflict(id) do nothing;
