insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('3ab430bc-032a-46e5-852b-26d6ea080877','sd-bacaan',1,'lesson','SD','bacaan','Cerita hewan di rumah','{"description":"Baca cerita pendek memakai kosakata di Kamus Visual SD.","emoji":"🐟","word":"Ikan","words":["Ikan","Ayam","Kambing"],"time":10,"intro":"Kamu akan mencari siapa, tempat, dan kegiatan dalam cerita tentang hewan peliharaan.","explanation":"Dina melihat hewan di rumah pagi hari. Ayam berada di kandang. Kambing makan rumput. Ikan berenang di kolam. Dina memberi makan ikan.","tip":"Cari satu informasi dulu: siapa, kapan, di mana, atau apa kegiatannya.","visual":"🐔 🐐 🐟","level":"Dasar","wordEntry":{"word":"Ikan","emoji":"🐟","category":"Hewan","meaning":"Hewan yang hidup di air dan bernapas dengan insang.","example":"Ikan berenang di kolam.","videoId":"3KepM1ycETA","start":165,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}},"relatedWords":[{"word":"Ikan","emoji":"🐟","category":"Hewan","meaning":"Hewan yang hidup di air dan bernapas dengan insang.","example":"Ikan berenang di kolam.","videoId":"3KepM1ycETA","start":165,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}},{"word":"Ayam","emoji":"🐔","category":"Hewan","meaning":"Hewan unggas yang memiliki paruh, sayap, dan dua kaki.","example":"Ayam dapat dipelihara di rumah.","videoId":"3KepM1ycETA","start":75,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}},{"word":"Kambing","emoji":"🐐","category":"Hewan","meaning":"Hewan berkaki empat yang biasa dipelihara sebagai ternak.","example":"Kambing berada di dalam kandang.","videoId":"3KepM1ycETA","start":110,"video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}}],"example":"Ikan berenang di kolam.","video":{"id":"3KepM1ycETA","title":"Mengenal hewan peliharaan","creator":"Direktorat PKPLK","topic":"Kosakata hewan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Pelajari nama dan ciri hewan peliharaan melalui materi tematik kelas 4 SDLB tunarungu dengan penjelasan isyarat dan gambar.","sourceTitle":"Pembelajaran tematik kelas IV SDLB Tunarungu \"Hewan Peliharaan\""}}'::jsonb,'published') on conflict(id) do nothing;
