insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('8bcc69b1-f6b9-42a2-886c-b8a891af8c53','sd-hitung',1,'lesson','SD','akademik','Menghitung buah','{"description":"Latih penjumlahan dan pengurangan dengan mangga dan jeruk.","emoji":"🍊","word":"Jeruk","words":["Jeruk","Mangga","Pepaya"],"time":8,"intro":"Kamu akan menghitung jumlah buah yang namanya sudah kamu kenal di Kamus Visual.","explanation":"Ada 2 jeruk dan 1 jeruk lagi. Jumlahnya 3 jeruk: 2 + 1 = 3. Jika 1 jeruk diberikan kepada teman, tersisa 2 jeruk: 3 − 1 = 2.","tip":"Hitung satu per satu. Tambah berarti digabungkan; kurang berarti diambil sebagian.","visual":"🍊🍊 + 🍊","level":"Dasar","wordEntry":{"word":"Jeruk","emoji":"🍊","category":"Tumbuhan","meaning":"Buah berkulit tebal dengan bagian dalam berupa beberapa ulas.","example":"Ada dua buah jeruk pada gambar.","videoId":"iDDkYTki6pU","start":225,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}},"relatedWords":[{"word":"Jeruk","emoji":"🍊","category":"Tumbuhan","meaning":"Buah berkulit tebal dengan bagian dalam berupa beberapa ulas.","example":"Ada dua buah jeruk pada gambar.","videoId":"iDDkYTki6pU","start":225,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}},{"word":"Mangga","emoji":"🥭","category":"Tumbuhan","meaning":"Buah yang tumbuh pada pohon mangga.","example":"Pohon mangga menghasilkan buah mangga.","videoId":"iDDkYTki6pU","start":80,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}},{"word":"Pepaya","emoji":"🌱","category":"Tumbuhan","meaning":"Buah yang tumbuh pada tanaman pepaya.","example":"Kita menghitung buah pepaya pada gambar.","videoId":"iDDkYTki6pU","start":165,"video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}}],"example":"Ada dua buah jeruk pada gambar.","video":{"id":"iDDkYTki6pU","title":"Tumbuhan di sekitar kita","creator":"Direktorat PKPLK","topic":"Kosakata tumbuhan","sourceLevel":"SDLB · Kelas 4","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Kenali tumbuhan melalui pembelajaran Bahasa Indonesia kelas 4 untuk peserta didik tunarungu, dengan isyarat dan gambar.","sourceTitle":"Pembelajaran Bahasa Indonesia Kelas IV Tunarungu\"Tumbuhan Disekitar Kita\""}}'::jsonb,'published') on conflict(id) do nothing;
