insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('fdbffe83-06dd-4e25-8f47-94ffb7460bd3','smp-percakapan',1,'lesson','SMP','kosakata','Kosakata percakapan sopan','{"description":"Pahami sekolah, sopan, dan permisi dari video SMPLB.","emoji":"🏫","word":"Sekolah","words":["Sekolah","Sopan","Permisi"],"time":8,"intro":"Kamu akan memahami kosakata percakapan yang muncul pada video dan Kamus Visual SMP.","explanation":"Sekolah adalah tempat belajar. Sopan berarti menghargai orang lain dalam perilaku dan ucapan. Permisi digunakan saat meminta izin atau perhatian dengan sopan.","tip":"Perhatikan situasinya: di mana kamu berada, kepada siapa kamu berbicara, dan apa yang ingin kamu sampaikan.","visual":"🏫 🤝 🙋","level":"Menengah","wordEntry":{"word":"Sekolah","emoji":"🏫","category":"Tempat","meaning":"Tempat peserta didik belajar bersama guru.","example":"Kita bersikap sopan di lingkungan sekolah.","videoId":"5TJG1D3OG1Y","start":285,"video":{"id":"5TJG1D3OG1Y","title":"Bahasa Indonesia melalui percakapan","creator":"Rapusa","topic":"Percakapan dan bacaan","sourceLevel":"SMPLB · Kelas 7","audience":"tunarungu","accessibility":"Komunikasi visual & teks","description":"Ikuti rekaman pembelajaran Bahasa Indonesia kelas 7 SMPLB tunarungu dengan percakapan, komunikasi visual, dan teks di papan.","sourceTitle":"Praktik Pembelajaran Bahasa Indonesia  - Kelas VII SMPLB Tunarungu"}},"relatedWords":[{"word":"Sekolah","emoji":"🏫","category":"Tempat","meaning":"Tempat peserta didik belajar bersama guru.","example":"Kita bersikap sopan di lingkungan sekolah.","videoId":"5TJG1D3OG1Y","start":285,"video":{"id":"5TJG1D3OG1Y","title":"Bahasa Indonesia melalui percakapan","creator":"Rapusa","topic":"Percakapan dan bacaan","sourceLevel":"SMPLB · Kelas 7","audience":"tunarungu","accessibility":"Komunikasi visual & teks","description":"Ikuti rekaman pembelajaran Bahasa Indonesia kelas 7 SMPLB tunarungu dengan percakapan, komunikasi visual, dan teks di papan.","sourceTitle":"Praktik Pembelajaran Bahasa Indonesia  - Kelas VII SMPLB Tunarungu"}},{"word":"Sopan","emoji":"🤝","category":"Sikap","meaning":"Berperilaku baik dan menghargai orang lain.","example":"Kita berbicara dengan sopan kepada guru.","videoId":"5TJG1D3OG1Y","start":405,"video":{"id":"5TJG1D3OG1Y","title":"Bahasa Indonesia melalui percakapan","creator":"Rapusa","topic":"Percakapan dan bacaan","sourceLevel":"SMPLB · Kelas 7","audience":"tunarungu","accessibility":"Komunikasi visual & teks","description":"Ikuti rekaman pembelajaran Bahasa Indonesia kelas 7 SMPLB tunarungu dengan percakapan, komunikasi visual, dan teks di papan.","sourceTitle":"Praktik Pembelajaran Bahasa Indonesia  - Kelas VII SMPLB Tunarungu"}},{"word":"Permisi","emoji":"🙋","category":"Ungkapan","meaning":"Ungkapan untuk meminta izin atau perhatian dengan sopan.","example":"Permisi, saya ingin lewat.","videoId":"5TJG1D3OG1Y","start":410,"video":{"id":"5TJG1D3OG1Y","title":"Bahasa Indonesia melalui percakapan","creator":"Rapusa","topic":"Percakapan dan bacaan","sourceLevel":"SMPLB · Kelas 7","audience":"tunarungu","accessibility":"Komunikasi visual & teks","description":"Ikuti rekaman pembelajaran Bahasa Indonesia kelas 7 SMPLB tunarungu dengan percakapan, komunikasi visual, dan teks di papan.","sourceTitle":"Praktik Pembelajaran Bahasa Indonesia  - Kelas VII SMPLB Tunarungu"}}],"example":"Kita bersikap sopan di lingkungan sekolah.","video":{"id":"5TJG1D3OG1Y","title":"Bahasa Indonesia melalui percakapan","creator":"Rapusa","topic":"Percakapan dan bacaan","sourceLevel":"SMPLB · Kelas 7","audience":"tunarungu","accessibility":"Komunikasi visual & teks","description":"Ikuti rekaman pembelajaran Bahasa Indonesia kelas 7 SMPLB tunarungu dengan percakapan, komunikasi visual, dan teks di papan.","sourceTitle":"Praktik Pembelajaran Bahasa Indonesia  - Kelas VII SMPLB Tunarungu"}}'::jsonb,'published') on conflict(id) do nothing;
