insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('65bec73a-79bb-44b5-8dd7-2b20abf24282','smp-kalimat',1,'lesson','SMP','kalimat','Menyampaikan izin dengan santun','{"description":"Pilih kalimat yang tepat untuk percakapan di sekolah.","emoji":"🙋","word":"Permisi","words":["Permisi","Sopan","Sekolah"],"time":10,"intro":"Kamu akan menyusun ungkapan izin dan memilih kalimat yang sesuai dengan situasi.","explanation":"Kalimat “Permisi, saya ingin lewat.” menyampaikan tujuan dengan sopan. Saat ingin bertanya kepada guru, gunakan “Permisi, boleh saya bertanya?”","tip":"Gunakan ungkapan sopan, sebutkan dirimu, lalu sampaikan tujuanmu dengan jelas.","visual":"🙋 🏫","level":"Menengah","wordEntry":{"word":"Permisi","emoji":"🙋","category":"Ungkapan","meaning":"Ungkapan untuk meminta izin atau perhatian dengan sopan.","example":"Permisi, saya ingin lewat.","videoId":"5TJG1D3OG1Y","start":410,"video":{"id":"5TJG1D3OG1Y","title":"Bahasa Indonesia melalui percakapan","creator":"Rapusa","topic":"Percakapan dan bacaan","sourceLevel":"SMPLB · Kelas 7","audience":"tunarungu","accessibility":"Komunikasi visual & teks","description":"Ikuti rekaman pembelajaran Bahasa Indonesia kelas 7 SMPLB tunarungu dengan percakapan, komunikasi visual, dan teks di papan.","sourceTitle":"Praktik Pembelajaran Bahasa Indonesia  - Kelas VII SMPLB Tunarungu"}},"relatedWords":[{"word":"Permisi","emoji":"🙋","category":"Ungkapan","meaning":"Ungkapan untuk meminta izin atau perhatian dengan sopan.","example":"Permisi, saya ingin lewat.","videoId":"5TJG1D3OG1Y","start":410,"video":{"id":"5TJG1D3OG1Y","title":"Bahasa Indonesia melalui percakapan","creator":"Rapusa","topic":"Percakapan dan bacaan","sourceLevel":"SMPLB · Kelas 7","audience":"tunarungu","accessibility":"Komunikasi visual & teks","description":"Ikuti rekaman pembelajaran Bahasa Indonesia kelas 7 SMPLB tunarungu dengan percakapan, komunikasi visual, dan teks di papan.","sourceTitle":"Praktik Pembelajaran Bahasa I