insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('3a3c484e-ae63-4fc0-8758-44ad33108f6b','smp-rencana',1,'lesson','SMP','akademik','Menghitung rencana rekreasi','{"description":"Gunakan waktu dan jumlah orang dalam konteks rekreasi.","emoji":"🏖️","word":"Rekreasi","words":["Rekreasi","Pelabuhan"],"time":10,"intro":"Kamu akan memakai kosakata rekreasi dan pelabuhan untuk berlatih menghitung waktu serta jumlah orang.","explanation":"Keluarga berangkat pukul 08.00 dan tiba di pelabuhan pukul 09.00. Perjalanan berlangsung 1 jam atau 60 menit. Ada 3 orang dewasa dan 2 anak; jumlahnya 5 orang.","tip":"Pisahkan informasi waktu dan jumlah orang. Tulis perhitungannya sebelum memilih jawaban.","visual":"🕗 → 🕘 🚢","level":"Menengah","wordEntry":{"word":"Rekreasi","emoji":"🏖️","category":"Kegiatan","meaning":"Kegiatan untuk menyegarkan pikiran atau bersenang-senang.","example":"Kita berekreasi bersama keluarga.","videoId":"XmiXc0YUrXY","start":285,"video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}},"relatedWords":[{"word":"Rekreasi","emoji":"🏖️","category":"Kegiatan","meaning":"Kegiatan untuk menyegarkan pikiran atau bersenang-senang.","example":"Kita berekreasi bersama keluarga.","videoId":"XmiXc0YUrXY","start":285,"video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}},{"word":"Pelabuhan","emoji":"🚢","category":"Tempat","meaning":"Tempat kapal berlabuh untuk menaikkan atau menurunkan penumpang dan barang.","example":"Kapal berhenti di pelabuhan.","videoId":"XmiXc0YUrXY","start":585,"video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}}],"example":"Kita berekreasi bersama keluarga.","video":{"id":"XmiXc0YUrXY","title":"Memahami isi paragraf sederhana","creator":"Melalita Anggraeni","topic":"Pemahaman bacaan","sourceLevel":"SMPLB · Kelas 9","audience":"tunarungu","accessibility":"Isyarat & media visual","description":"Amati rekaman pembelajaran kelas 9 tunarungu untuk memahami paragraf sederhana dengan interaksi isyarat dan media visual.","sourceTitle":"VIDEO PEMBELAJARAN SISWA TUNARUNGU KELAS IX BAHASA INDONESIA"}}'::jsonb,'published') on conflict(id) do nothing;
