insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('b25387bc-8c7e-45c8-86fb-c5b8ad516773','sma-kosakata',1,'lesson','SMA','kosakata','Kosakata isyarat dalam konteks','{"description":"Bedakan kosakata tempat dan buah pada video SMALB-B.","emoji":"📍","word":"Purwakarta","words":["Purwakarta","Jambu","Inggris"],"time":8,"intro":"Kamu akan mengamati kosakata isyarat dan membedakan maknanya berdasarkan konteks serta kategori.","explanation":"Purwakarta adalah nama kabupaten di Jawa Barat. Inggris adalah nama negara yang merupakan bagian dari Britania Raya. Jambu adalah nama buah; gambar pada video menunjukkan jambu air.","tip":"Cocokkan kata, gambar, dan kategori. Nama tempat dan nama buah memiliki konteks yang berbeda.","visual":"📍 🍎 🇬🇧","level":"Lanjutan","wordEntry":{"word":"Purwakarta","emoji":"📍","category":"Tempat","meaning":"Nama kabupaten di Provinsi Jawa Barat.","example":"Purwakarta diperagakan dalam video kosakata isyarat.","videoId":"EBTZFitRSEc","start":80,"video":{"id":"EBTZFitRSEc","title":"Kosakata sehari-hari dalam bahasa isyarat","creator":"SLBN BOGOR","topic":"Kosakata dan komunikasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Belajar kosakata tempat dan buah melalui gambar dan peragaan isyarat bersama peserta didik SMALB-B tunarungu dari SLBN Bogor.","sourceTitle":"#05_GURLING | BELAJAR BAHASA ISYARAT ALA PESERTA DIDIK SLBN BOGOR - SMALB B (TUNARUNGU) - SLBN BOGOR"}},"relatedWords":[{"word":"Purwakarta","emoji":"📍","category":"Tempat","meaning":"Nama kabupaten di Provinsi Jawa Barat.","example":"Purwakarta diperagakan dalam video kosakata isyarat.","videoId":"EBTZFitRSEc","start":80,"video":{"id":"EBTZFitRSEc","title":"Kosakata sehari-hari dalam bahasa isyarat","creator":"SLBN BOGOR","topic":"Kosakata dan komunikasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Belajar kosakata tempat dan buah melalui gambar dan peragaan isyarat bersama peserta didik SMALB-B tunarungu dari SLBN Bogor.","sourceTitle":"#05_GURLING | BELAJAR BAHASA ISYARAT ALA PESERTA DIDIK SLBN BOGOR - SMALB B (TUNARUNGU) - SLBN BOGOR"}},{"word":"Jambu","emoji":"🍎","category":"Buah","meaning":"Nama kelompok buah; pada video ditunjukkan gambar jambu air.","example":"Gambar jambu membantu mengenali kata yang diperagakan.","videoId":"EBTZFitRSEc","start":110,"video":{"id":"EBTZFitRSEc","title":"Kosakata sehari-hari dalam bahasa isyarat","creator":"SLBN BOGOR","topic":"Kosakata dan komunikasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Belajar kosakata tempat dan buah melalui gambar dan peragaan isyarat bersama peserta didik SMALB-B tunarungu dari SLBN Bogor.","sourceTitle":"#05_GURLING | BELAJAR BAHASA ISYARAT ALA PESERTA DIDIK SLBN BOGOR - SMALB B (TUNARUNGU) - SLBN BOGOR"}},{"word":"Inggris","emoji":"🇬🇧","category":"Tempat","meaning":"Nama negara yang merupakan bagian dari Britania Raya.","example":"Kata Inggris diperagakan bersama gambar bendera dalam video.","videoId":"EBTZFitRSEc","start":170,"video":{"id":"EBTZFitRSEc","title":"Kosakata sehari-hari dalam bahasa isyarat","creator":"SLBN BOGOR","topic":"Kosakata dan komunikasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Belajar kosakata tempat dan buah melalui gambar dan peragaan isyarat bersama peserta didik SMALB-B tunarungu dari SLBN Bogor.","sourceTitle":"#05_GURLING | BELAJAR BAHASA ISYARAT ALA PESERTA DIDIK SLBN BOGOR - SMALB B (TUNARUNGU) - SLBN BOGOR"}}],"example":"Purwakarta diperagakan dalam video kosakata isyarat.","video":{"id":"EBTZFitRSEc","title":"Kosakata sehari-hari dalam bahasa isyarat","creator":"SLBN BOGOR","topic":"Kosakata dan komunikasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat, gambar & teks","description":"Belajar kosakata tempat dan buah melalui gambar dan peragaan isyarat bersama peserta didik SMALB-B tunarungu dari SLBN Bogor.","sourceTitle":"#05_GURLING | BELAJAR BAHASA ISYARAT ALA PESERTA DIDIK SLBN BOGOR - SMALB B (TUNARUNGU) - SLBN BOGOR"}}'::jsonb,'published') on conflict(id) do nothing;
