insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('f829d025-3eeb-4cb5-816a-a4f0cb02d198','sma-kalimat',1,'lesson','SMA','kalimat','Kalimat sebab dan akibat','{"description":"Hubungkan hujan dan banjir dalam kalimat yang logis.","emoji":"🌧️","word":"Hujan","words":["Hujan","Banjir","Eksplanasi"],"time":10,"intro":"Kamu akan membedakan penyebab dan akibat menggunakan kosakata pada materi eksplanasi.","explanation":"“Air sulit mengalir karena saluran tersumbat.” menyatakan penyebab. “Hujan deras membuat air bertambah sehingga jalan tergenang.” menunjukkan hubungan sebab dan akibat.","tip":"Cari kata “karena” untuk penyebab dan “sehingga” untuk akibat. Baca seluruh kalimat agar hubungan informasinya jelas.","visual":"🌧️ → 🌊","level":"Lanjutan","wordEntry":{"word":"Hujan","emoji":"🌧️","category":"Peristiwa","meaning":"Air yang jatuh dari awan ke permukaan bumi dalam bentuk titik-titik air.","example":"Hujan merupakan salah satu peristiwa alam.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},"relatedWords":[{"word":"Hujan","emoji":"🌧️","category":"Peristiwa","meaning":"Air yang jatuh dari awan ke permukaan bumi dalam bentuk titik-titik air.","example":"Hujan merupakan salah satu peristiwa alam.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},{"word":"Banjir","emoji":"🌊","category":"Peristiwa","meaning":"Peristiwa meluapnya air sehingga menggenangi wilayah yang biasanya kering.","example":"Air yang meluap dapat menyebabkan banjir.","videoId":"cvwI6-6lfGY","start":165,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}},{"word":"Eksplanasi","emoji":"📝","category":"Teks","meaning":"Penjelasan tentang bagaimana atau mengapa suatu peristiwa terjadi.","example":"Teks eksplanasi menjelaskan proses terjadinya hujan.","videoId":"cvwI6-6lfGY","start":75,"video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}}],"example":"Hujan merupakan salah satu peristiwa alam.","video":{"id":"cvwI6-6lfGY","title":"Memahami teks eksplanasi","creator":"SMALB KM","topic":"Teks eksplanasi","sourceLevel":"SMALB-B","audience":"tunarungu","accessibility":"Isyarat & teks pada layar","description":"Pelajari teks eksplanasi dari SMALB-B Karya Mulia Surabaya melalui penjelasan isyarat dan teks yang tampil di layar.","sourceTitle":"Video Bahasa Indonesia SMALB_B Karya Mulia Surabaya"}}'::jsonb,'published') on conflict(id) do nothing;
