insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('bcd1f700-3aa5-4a4e-8efd-82672955ad2a','basic-kosakata',1,'basic','ALL','kosakata','Mengenal kata dan arti','{"slides":[["Kosakata di sekitar kita","Kata membantu kita mengenali benda dan kegiatan."],["Buku dan pensil","Buku berisi halaman untuk dibaca.","Pensil digunakan untuk menulis dan menggambar."],["Menyiram tanaman","Menyiram berarti memberi air pada tanaman.","Tanaman membutuhkan air agar tetap segar."],["Coba ingat kembali","Kenali benda, lalu cocokkan dengan namanya.","Bedakan nama benda dan kata kegiatan."]],"videoSrc":"/videos/basic-kosakata.webm"}'::jsonb,'published') on conflict(id) do nothing;
insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('999c35ef-0617-4246-8f14-9af08010bc85','basic-kalimat',1,'basic','ALL','kalimat','Memahami dan menyusun kalimat','{"slides":[["Kalimat sederhana","Kalimat menjelaskan siapa melakukan kegiatan."],["Dina membaca buku.","Siapa? Dina.","Kegiatan? Membaca. Benda yang dibaca? Buku."],["Urutan kegiatan","Sebelum makan, Budi mencuci tangan.","Mencuci tangan dilakukan lebih dulu, lalu makan."],["Coba susun kalimat","Mulai dari siapa, lalu kegiatan, lalu benda.","Contoh: Ibu menyiram tanaman."]],"videoSrc":"/videos/basic-kalimat.webm"}'::jsonb,'published') on conflict(id) do nothing;
insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('fbd8e5a9-a425-48f7-8d58-3c4831a40873','basic-bacaan',1,'basic','ALL','bacaan','Menemukan informasi dalam bacaan','{"slides":[["Membaca cerita pendek","Baca pelan-pelan. Cari siapa, tempat, dan kegiatan."],["Dina di taman","Dina pergi ke taman. Ia menyiram bunga.","Siapa? Dina. Di mana? Di taman."],["Memahami sebab dan tujuan","Bunga layu karena tanahnya kering.","Dina memberi air agar bunga kembali segar."],["Temukan jawabannya","Cari informasi di dalam cerita.","Mengapa memberi air? Agar bunga segar."]],"videoSrc":"/videos/basic-bacaan.webm"}'::jsonb,'published') on conflict(id) do nothing;
insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status) values('3da62652-1d77-4cef-8c81-e44b1ee9f1a6','basic-akademik',1,'basic','ALL','akademik','Penjumlahan dan pengurangan dasar','{"slides":[["Ayo menghitung","Hitung benda satu per satu."],["Penjumlahan: 2 + 1 = 3","Ada dua apel. Tambahkan satu apel.","Jumlah seluruhnya menjadi tiga apel."],["Pengurangan: 5 - 2 = 3","Ada lima apel. Dua apel diberikan kepada Dina.","Apel yang tersisa adalah tiga."],["Coba ingat kembali","Tambah: gabungkan jumlah benda.","Kurang: ambil sebagian, lalu hitung sisanya."]],"videoSrc":"/videos/basic-akademik.webm"}'::jsonb,'published') on conflict(id) do nothing;
